// Drop the live URL into the post body. LinkedIn builds its own link preview
// from a URL in the text, so no media fields are needed.
const item = $input.first().json;
return [{
  json: {
    portfolioUrl: item.portfolioUrl,
    postText: item.postText.replace('{{PORTFOLIO_URL}}', item.portfolioUrl)
  }
}];
